function countUp(el){const to=+el.dataset.count,t0=performance.now(),dur=900;if(reduceMotion())return;const step=t=>{const k=Math.min(1,(t-t0)/dur);el.textContent=Math.round(to*(1-(1-k)**3));if(k<1)requestAnimationFrame(step)};el.textContent='0';requestAnimationFrame(step);setTimeout(()=>{el.textContent=to},dur+200)}
